{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 쿼리의 병목에 맞는 개선 방법을 선택할 수 있는지 검증한다. 신고 목록 조회 쿼리의 개선 방법을 고른 이유를 통해 원인 분석과 개선 선택, 측정된 효과의 연결을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리에 3.2초가 걸렸던 상황이다.",
          "task": "조회 지연의 원인에 맞는 쿼리 개선 방법을 선택해야 했다.",
          "action": "실행 계획에서 확인한 병목을 바탕으로 선택한 개선 방법이 적절했던 이유를 설명한다.",
          "result": "3.2초에서 0.4초로 줄어든 측정 결과를 선택한 방법의 효과와 연결한다. 비교 조건과 측정 방식은 실제 경험한 범위에서 설명한다."
        },
        "expectedEvidence": [
          "쿼리 개선 방법을 선택한 이유와 확인한 병목 사이의 연결",
          "실행 계획이나 조회 구조에서 확인한 구체적인 병목의 증거",
          "개선 전후 응답 시간의 측정 결과와 비교 조건에 대한 설명"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리를 3.2초에서 0.4초로 줄이셨네요. 당시 쿼리 개선 방법을 고른 이유는 무엇이었나요?",
      "answerTip": "당시 관찰한 사실과 본인의 해석을 나눠 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "선택한 개선 방법이 확인된 병목에 적합했던 이유를 구체적으로 설명한다.",
            "실행 계획이나 조회 구조에서 발견한 증거가 해당 방법의 선택으로 이어지는 논리가 명확하다.",
            "개선 전후 수치와 비교 조건을 설명하여 선택한 방법의 효과를 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "개선 방법을 선택한 이유는 설명하지만 병목과의 연결이 일부 추상적이다.",
            "실행 계획이나 조회 구조를 언급하지만 실제로 확인한 증거의 설명이 부족하다.",
            "개선 전후 수치는 제시하지만 측정 방식이나 비교 조건이 불명확하다."
          ]
        },
        "poor": {
          "criteria": [
            "개선 방법을 고른 이유 없이 수행한 수정 사항만 나열한다.",
            "실제 병목의 증거 없이 인덱스나 쿼리 수정의 일반적인 장점만 설명한다.",
            "개선 효과를 수치로 뒷받침하지 못하거나 제시한 수치가 선택한 방법과 어떻게 연결되는지 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류의 원인을 로그로 추적하여 좁힐 수 있는지 검증한다. 알림 중복 발송을 클라이언트 문제가 아닌 스케줄러 문제로 판단하게 한 결정적인 단서를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의를 받았고, 처음에는 클라이언트 문제로 생각했던 상황이다.",
          "task": "알림 중복 발송의 실제 원인이 어디에 있는지 판단해야 했다.",
          "action": "시간순으로 살펴본 로그에서 어떤 관찰이 스케줄러 중복 실행을 가리켰는지 설명하고, 그 단서가 기존 추정과 달랐던 이유를 밝힌다.",
          "result": "스케줄러가 서버 두 대에서 동시에 실행된 것이 중복 발송의 원인이라는 판단이 로그의 관찰 사실로 뒷받침된다."
        },
        "expectedEvidence": [
          "클라이언트가 아닌 스케줄러 문제로 판단하게 한 결정적인 로그 단서",
          "서버 두 대의 스케줄러 동시 실행을 뒷받침하는 시간순 로그의 관찰 사실",
          "관찰한 단서가 알림 중복 발송을 설명하며 기존 클라이언트 문제 추정과 구별되는 이유"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 수정하셨네요. 클라이언트가 아닌 스케줄러 문제라고 판단한 결정적인 단서를 들려주세요.",
      "answerTip": "처음 추정과 생각을 바꾼 지점을 대비해 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "스케줄러 문제로 판단하게 한 결정적인 로그 단서를 명확하게 제시한다.",
            "시간순 로그에서 서버 두 대의 동시 실행을 식별한 관찰 사실을 구체적으로 설명한다.",
            "해당 단서가 중복 발송을 설명하는 이유와 클라이언트 문제 추정을 수정한 이유가 논리적으로 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "스케줄러 문제로 판단한 단서는 제시하지만 로그의 구체적인 설명이 부족하다.",
            "서버 두 대의 동시 실행을 언급하지만 이를 로그에서 구별한 설명이 제한적이다.",
            "중복 발송과 스케줄러 실행의 관련성은 설명하지만 기존 추정을 바꾼 이유가 충분하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "결정적인 단서를 제시하지 않고 스케줄러가 원인이었다는 결론만 말한다.",
            "로그에서 관찰한 사실과 본인의 추측을 구분하지 못한다.",
            "스케줄러 실행이 중복 발송을 설명하는 이유 없이 수정 조치나 일반적인 장애 대응만 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "요청의 목적을 바탕으로 구현 범위를 구체화할 수 있는지 검증한다. 요구사항 정의서 작성 경험에서 개발 담당 팀원과 조정한 구현 범위를 정한 기준 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳의 인터뷰를 바탕으로 요구사항 정의서를 작성한 상황과 범위 조정이 필요했던 요청이 제시된다.",
          "task": "서비스가 해결할 문제에 맞춰 이번 구현에 포함할 범위의 경계를 정해야 했던 본인의 과제가 드러난다.",
          "action": "인터뷰에서 확인한 목적에 비추어 요청의 포함 여부를 판단한 기준을 설명하고, 실제 범위 결정에 적용한 사례를 제시한다.",
          "result": "그 기준으로 포함하거나 제외한 범위가 명확해진 지점과 개발 담당 팀원과 조정한 범위가 드러난다. 구현 완료나 성과 수치를 필수로 요구하지 않는다."
        },
        "expectedEvidence": [
          "개발 담당 팀원과 조정한 구현 범위를 정한 구체적인 판단 기준",
          "해당 기준을 뒷받침하는 인터뷰 요청의 목적과 해결할 문제",
          "기준을 실제 요청에 적용해 포함하거나 제외한 범위의 경계"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳 인터뷰로 요구사항 정의서를 작성하셨습니다. 개발 담당 팀원과 조정한 구현 범위는 어떤 기준으로 정하셨나요?",
      "answerTip": "실제 요청 하나를 골라 포함 여부와 이유를 연결해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구현 범위를 정한 기준이 명확하고, 실제 요청의 포함 여부를 판단한 사례로 설명한다.",
            "그 기준이 인터뷰에서 확인한 요청의 목적과 해결할 문제에 어떻게 연결되는지 설명한다.",
            "포함하거나 제외한 범위의 경계를 개발 담당자가 구분할 수 있을 만큼 구체적으로 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현 범위를 정한 기준은 제시하지만 실제 요청에 적용한 설명이 일부 부족하다.",
            "요청의 목적 또는 포함 여부는 확인되지만, 해당 기준과 범위 경계의 연결이 충분히 명확하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "구현 범위를 정한 기준을 제시하지 못하거나 작성한 기능 목록만 나열한다.",
            "인터뷰 요청의 목적과 무관한 설명에 머물거나, 무엇을 포함하거나 제외했는지 구분할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황에서도 구현 가능한 화면 동작을 구체화할 수 있는지 검증한다. 화면설계서 작성 경험에서 예외 상황의 화면 처리 방식을 정하며 가장 고민한 판단 하나를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스의 Figma 화면설계서 28장에 포함한 예외 상황 중 실제로 화면 처리 방식을 고민한 장면이 제시된다.",
          "task": "해당 예외 상황에서 사용자가 마주할 화면 동작을 구현 가능한 수준으로 정해야 했던 본인의 과제가 드러난다.",
          "action": "화면 처리 방식에서 고민한 선택과 그 이유를 설명하고, 기능 흐름에 비추어 특정 방식을 선택한 판단을 제시한다.",
          "result": "선택한 방식에 따라 예외 발생 시 화면이 어떤 상태가 되는지 분명해진다. 실제 개발 완료나 사용자 성과는 필수로 요구하지 않는다."
        },
        "expectedEvidence": [
          "예외 상황의 화면 처리 방식을 정할 때 가장 고민한 판단과 선택한 방향",
          "그 고민을 낳은 구체적인 예외 조건과 사용자 흐름상의 영향",
          "선택한 처리 방식이 화면 상태나 안내에 어떻게 구체화되는지에 대한 설명"
        ]
      },
      "question": "동네 세탁소 예약 서비스의 화면설계서 28장을 Figma로 작성하셨습니다. 예외 상황의 화면 처리 방식을 정할 때 가장 고민한 지점은 무엇이었나요?",
      "answerTip": "고민했던 선택지와 최종 선택을 나눠 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황의 화면 처리 방식에서 가장 고민한 판단을 구체적인 선택과 연결해 설명한다.",
            "예외가 발생하는 조건과 사용자 흐름에 미치는 영향을 바탕으로 선택 이유를 설명한다.",
            "선택한 방식에 따른 화면 상태나 안내를 구현자가 동작을 해석할 수 있을 만큼 명확하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "화면 처리 방식에서 고민한 지점은 제시하지만 선택 이유나 최종 방향이 충분히 구체적이지 않다.",
            "예외 조건과 화면 처리의 연결은 일부 확인되지만, 실제 화면 동작을 이해하는 데 필요한 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "화면 처리 방식에서 고민한 판단이 드러나지 않고 예외 상황의 이름이나 화면 수만 제시한다.",
            "예외 조건에 따른 화면 동작을 설명하지 못하거나, 선택한 방식이 사용자 흐름과 연결되지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방의 이상 여부를 확인하지 않은 채 투약하지 않고 수행을 중단할 수 있는지 검증한다. 평소의 두 배로 입력된 진통제 처방에서 투약을 멈추기로 한 판단의 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소의 두 배로 입력되어 있었던 당시 상황을 설명한다.",
          "task": "처방대로 투약해도 되는지 확인되지 않은 상태에서 투약 진행 여부를 판단해야 했음을 설명한다.",
          "action": "당시 확인한 처방 정보와 의심한 지점을 연결해, 담당의 확인 전 투약을 멈춘 이유를 설명한다.",
          "result": "담당의 확인 결과 입력 오류였다는 사실을 자신의 중단 판단과 연결해 설명한다."
        },
        "expectedEvidence": [
          "진통제 투약을 멈추기로 한 구체적인 판단 근거",
          "처방에서 직접 확인한 사실과 투약 가능 여부에 대한 불확실성의 연결",
          "담당의 확인으로 밝혀진 입력 오류와 중단 판단의 관계"
        ]
      },
      "question": "수술 후 환자의 진통제 처방 용량이 평소의 두 배로 들어온 경험을 적어주셨습니다. 당시 투약을 멈추기로 한 판단의 근거는 무엇이었나요?",
      "answerTip": "당시 알았던 사실과 확인 뒤 알게 된 사실을 나눠 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
